// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token bucket.
type Limiter struct {
	mu    sync.Mutex
	clock Clock
	rate  float64 // tokens per second
	burst float64
	tokens float64
	last  time.Time
}

// New creates a Limiter. rate is tokens/sec; burst is max tokens.
// A nil clock uses the system clock.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		clock: clock,
		rate:  rate,
		burst: float64(burst),
		tokens: float64(burst),
		last:  now,
	}, nil
}

// AllowN reports whether n tokens can be consumed, consuming them if so.
// n <= 0 is always allowed and consumes nothing.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if elapsed := now.Sub(l.last).Seconds(); elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token can be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Remaining returns the current estimated available tokens.
func (l *Limiter) Remaining() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	if elapsed := now.Sub(l.last).Seconds(); elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
	return l.tokens
}
